nodes.statement:
We assume that we are given a $p\times n$ matrix $\mathbf Y$ generated by the following model:
\begin{equation} \mathbf Y = \mathbf\Theta+\sigma\boldsymbol\Xi, \quad \xi_{i,j} \overset{\text{iid}}{\sim} \mathcal{N}(0,1).
\end{equation}
This means that the deterministic matrix $\mathbf\Theta$ is observed in Gaussian white noise of variance $\sigma^2$.
Equivalently, the columns $\boldsymbol Y\!_i$ of $\mathbf Y$ satisfy
\begin{equation}
	\boldsymbol Y\!_i = \boldsymbol\theta_i+\sigma\boldsymbol\xi_i, \quad \boldsymbol\xi_i \overset{\text{iid}}{\sim} \mathcal{N}(\mathbf 0_p,\mathbf I_p),\quad i=1,\ldots,n.
\end{equation}

In what follows, we denote by $\mathcal M(p,n,s)$ the set of all $p\times n$ matrices with real entries having at most $s$ nonzero columns:
\begin{equation} \mathcal M(p,n,s) = \Big\{\mathbf\Theta\in \mathbb R^{p\times n} : \sum_{i=1}^n \mathds 1(\|\boldsymbol\theta_i\|_2>0) \le s\Big\}.
\end{equation}

\setstretch{1.2}
\SetAlgoLined
\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
\Input{matrix $\mathbf Y$ and noise variance $\sigma$, threshold $\lambda$.}
\Output{vector $\widehat\boldsymbol L{}^{\rm GSS}$.}
initialization $I \gets [n]$ and $\widehat S \gets \varnothing$.\;
\Repeat{$I$ is empty or $\widehat J$ is empty}{
Set $\mathcal I \gets \big\{J\subseteq I : \|\boldsymbol L(\mathbf Y_{J})\|_2^2
\ge 12\sigma^2 (|J|p + \lambda |J|^2)\big\}$.\;
\eIf{$\mathcal I =\varnothing$}{$\widehat J\gets\varnothing$\;
}{
Set $\widehat J \gets \text{arg}\min\big\{|J| : J\in\mathcal I\big\}$.\;
}
Update $\widehat S \gets \widehat S \cup \widehat J$.\;
Update $I \gets I\setminus \widehat J$.\;
}
\Return{$\widehat\boldsymbol L{}^{\rm GSS}\gets \sum_{i\in\widehat S} \boldsymbol Y\!_i$}
\caption{Greedy subset selection algorithm}

Let $\delta\in(0,1)$ be a prescribed tolerance level. The greedy subset selection estimator
with $\lambda = \nicefrac32\log(\nicefrac{2n}{\delta})$ satisfies
\begin{equation} \sup_{\mathbf\Theta\in \mathcal M(p,n,s)}\mathbf P_\mathbf\Theta\Big(\|\widehat\boldsymbol L{}^{\rm GSS}
-\boldsymbol L(\mathbf\Theta)\|_2^2
    \le 60\sigma^2{s(p+\lambda s)}\Big) \ge 1-\delta.
\end{equation}

conclusions:
\sup_{\mathbf\Theta\in \mathcal M(p,n,s)}\mathbf P_\mathbf\Theta\Big(\|\widehat\boldsymbol L{}^{\rm GSS}
-\boldsymbol L(\mathbf\Theta)\|_2^2
    \le 60\sigma^2{s(p+\lambda s)}\Big) \ge 1-\delta.

nodes.statement:
\sup_{\mathbf\Theta\in \mathcal M(p,n,s)}\mathbf P_\mathbf\Theta\Big(\|\widehat\boldsymbol L{}^{\rm GSS}
-\boldsymbol L(\mathbf\Theta)\|_2^2
    \le 60\sigma^2{s(p+\lambda s)}\Big) \ge 1-\delta.

One easily checks that the foregoing optimization problem can be solved
explicitly and the resulting estimator is
\begin{equation}
	\widehat{\boldsymbol\theta}{}^{\rm GHT}_i = \boldsymbol Y\!_i \mathds{1}_{\|\boldsymbol Y\!_i\|_2 \ge \lambda},\qquad
	i\in[n].
\end{equation}

Let $\widehat{\boldsymbol L}{}^{\rm GHT}$ be the estimator defined in~\eqref{definition_LHT} with the tuning parameter
	\begin{equation}
		\lambda^2/\sigma^2 = p+4\big\{\log(1+n/s^2)\vee p^{1/2}\log^{1/2}(1+n^2p/s^4)\big\}.
	\end{equation}
	There exists a universal constant $c>0$ such that, for every
	$\mathbf\Theta\in\mathcal M(p,n,s)$, it holds
	\begin{equation}
		\mathbf E_\mathbf\Theta\big[\big\| \widehat{\boldsymbol L}{}^{\rm GHT}-\boldsymbol L(\mathbf\Theta) \big\|_2^2\big] \le 
		c\sigma^2\Big(s^2p^{1/2}\log^{1/2}(1+n^2p/s^4)+s^2\log(1+n/s^2)+sp\Big).
	\end{equation}

Let us denote by $\widehat{\boldsymbol L}{}^{\rm GHT}_\lambda$ the estimator defined in~\eqref{definition_LHT} with a threshold $\lambda>0$. There are two universal constants $p_0\in\mathbb N$ and $c>0$, such that for any $p\ge p_0$ and $s\le n/61$, the following lower bound holds
	\begin{equation}
		\inf_{\lambda>0}\sup_{\mathbf\Theta\in\mathcal M(p,n,s)} \mathbf E_\mathbf\Theta \big\| \widehat{\boldsymbol L}{}^{\rm GHT}_\lambda-\boldsymbol L(\mathbf\Theta) \big\|_2^2 \ge c\sigma^2\Big((s^2p^{1/2})\wedge (np)+s^2\log(1+n/s^2)+sp\Big).
	\end{equation}

In the model under consideration, the group soft thresholding estimator 
$\widehat{\mathbf\Theta}^{\rm GST}$
can be defined as the minimizer of the group-lasso cost function, that is
\begin{equation} \widehat{\mathbf\Theta}^{\rm GST} = \arg\min_{\mathbf{T}}
	\Big\{ \sum_{i=1}^n \| \boldsymbol Y\!_i - \boldsymbol{t}_i \|_2^2 + \sum_{i=1}^n \lambda_i \|\boldsymbol{t}_i\|_2 \Big\}.
\end{equation}

This problem has an explicit solution given by
\begin{equation} \widehat{\boldsymbol\theta}{}^{\,\rm GST}_i = \Big(1-\frac{\lambda_i}{2\|\boldsymbol Y\!_i\|_2}\Big)_+ \boldsymbol Y\!_i.
\end{equation}

The estimator $\widehat{\boldsymbol L}{}^{\rm GST}=\boldsymbol L(\widehat{\mathbf\Theta}^{\rm GST})$ defined
	in~\eqref{definition_STexplicite} with\footnote{Note that $\lambda_i=+\infty$
	if $\|\boldsymbol Y\!_i\|^2_2\le\sigma^2p$. This reflects
	the fact that there is no need to fit the signals of very low magnitude.}
	\begin{equation}
	\lambda_i = \frac{2\sigma\gamma\|\boldsymbol Y\!_i\|_2}{\big(\|\boldsymbol Y\!_i\|^2_2-\sigma^2p\big)_+^{1/2}}, \quad
	\gamma^2 = 
	4\big\{\log(1+n/s^2)\vee p^{1/2}\log^{1/2}(1+n^2p/s^4)
	\big\}
	\end{equation}
	satisfies, for every $\mathbf\Theta\in\mathcal M(p,n,s)$,
	\begin{equation}
	\mathbf E_\mathbf\Theta \big[\big\|\widehat{\boldsymbol L}{}^{\rm GST}-\boldsymbol L(\mathbf\Theta)\big\|^2 \big]
	\le c\sigma^2\Big(s^2p^{1/2}\log^{1/2}(1+n^2p/s^4)+s^2\log(1+n/s^2)+sp\Big),
	\end{equation}
	where $c>0$ is some universal constant.

Assume that $s\in[n]$, then there is a universal constant $c>0$ such that
	\begin{equation}
		\inf_{\widehat{\boldsymbol L}} \sup_{\mathbf\Theta\in\mathcal M(1,n,s)} \mathbf E_\mathbf\Theta \big( \widehat{\boldsymbol L}-\boldsymbol L(\mathbf\Theta) \big)^2 \ge c \sigma^2 s^2 \log(1+n/s^2).
	\end{equation}

Assume that $1\le s\le n$, then there is a universal constant $c>0$ such that
	\begin{equation}
		\inf_{\widehat{\boldsymbol L}} \sup_{\mathbf\Theta\in\mathcal M(p,n,s)} \mathbf E_\mathbf\Theta \big\| \widehat{\boldsymbol L}-\boldsymbol L(\mathbf\Theta) \big\|^2 \ge c \Big[ \sigma^2 s^2 \log(1+n/s^2)+\sigma^2 sp \Big].
	\end{equation}

\setstretch{1.2}
\SetAlgoLined
\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
\Input{matrix $\mathbf Y$, noise variance $\sigma^2$ and confidence level $\delta$.}
\Output{vector $\widehat\boldsymbol L{\!\!\!}^{\rm adGSS}$.}
Set ${\rm dist} \gets \sigma^{-1}\|\widehat\boldsymbol L{}^{\rm GSS}-\boldsymbol L(\mathbf Y)\|_2$.\;
Set $\lambda \gets \nicefrac32 \log(\nicefrac{4n}{\delta})$.\;
Set
$\widehat s \gets \min\Big\{k\in[n]: {\rm dist}\le \sqrt{60k(p+\lambda k)}+\sqrt{n(2p+3\log(2/\delta))}\Big\}$
(if the set is empty, set $\widehat s \gets n$)\;
\eIf{$60\widehat s(p+\lambda \widehat s)\le 2np+3n\log(2/\delta)$}
{$\widehat\boldsymbol L{}^{\rm adGSS}\gets \widehat\boldsymbol L{}^{\rm GSS}$\;}
{$\widehat\boldsymbol L{}^{\rm adGSS}\gets \boldsymbol L(\mathbf Y)$\;}
\Return{$\widehat\boldsymbol L{}^{\rm adGSS}$}
\caption{Adaptive GSS}

The problem of estimating the linear functional $\boldsymbol L_n(\boldsymbol\Theta) = (\nicefrac1n)\sum_{i\in[n]}
\boldsymbol\theta_i$ in model \eqref{definition_observation1} is not easier, in the minimax sense, than that of estimating $\boldsymbol\mu$. More precisely, we have
\begin{align}
\frac{\sigma^2 p}{n}\le \inf_{\widehat\boldsymbol\mu}\sup_{\boldsymbol\mu,\boldsymbol\Theta} \mathbf E[\|\widehat\boldsymbol\mu-\boldsymbol\mu\|_2^2]\le
2\inf_{\widehat\boldsymbol L_n}\sup_{\boldsymbol\Theta} \mathbf E[\|\widehat\boldsymbol L_n-\boldsymbol L_n(\boldsymbol\Theta)\|_2^2]
+\frac{2\sigma^2 p}{n},
\end{align}
where the sup in the left-hand side and in the right-hand side are taken,
respectively, over all $\boldsymbol\Theta\in\mathcal M(p,n,s)$ and over all $(\boldsymbol\mu,\boldsymbol\Theta)\in
\mathbb R^p\times\mathcal M(p,n,s)$.

Let $\widehat\boldsymbol\mu:\mathbb R^{p\times n}\to\mathbb R^p$ be an estimator of $\boldsymbol\mu$ that can be applied
both to the data matrix $\mathbf X = [\boldsymbol X_1,\ldots,\boldsymbol X_n]$ from Huber's model and to $\mathbf Y$ 
from our model \eqref{definition_observation}. Then, we have
\begin{align}
\underbrace{\sup_{\mathbf Q}\mathbf E_{\boldsymbol\mu,\mathbf Q}[\|\widehat\boldsymbol\mu(\mathbf X)-\boldsymbol\mu\|_2^2]}
_{\text{\rm risk in the Huber model}}\le
\mathbf E_{\widehat s\sim \mathcal B(n,s/n)}
\bigg[\underbrace{\sup_{\boldsymbol\Theta\in\mathcal M(n,p,\widehat s)}
\mathbf E_{\boldsymbol\mu,\boldsymbol\Theta}\big[\|\widehat\boldsymbol\mu(\mathbf Y)-\boldsymbol\mu\|_2^2\big]
}_{\text{\rm risk in our model \eqref{definition_observation}}}\bigg].
\end{align}
The supremum of the left-hand side is over all probability distributions $\mathbf Q$ on $\mathbb R^p$
such that\footnote{We denote by $*$ the convolution of the distributions.} 
$\mathbf Q = \mathbf Q_0 * \mathcal N_p(\mathbf 0, \sigma^2\mathbf I_p)$, 
while the notation $\mathcal B(n,s/n)$ stands for the binomial distribution.

\underbrace{\sup_{\mathbf Q}\mathbf E_{\boldsymbol\mu,\mathbf Q}[\|\widehat\boldsymbol\mu(\mathbf X)-\boldsymbol\mu\|_2^2]}
_{\text{\rm risk in the Huber model}}\le
\mathbf E_{\widehat s\sim \mathcal B(n,s/n)}
\bigg[\underbrace{\sup_{\boldsymbol\Theta\in\mathcal M(n,p,\widehat s)}
\mathbf E_{\boldsymbol\mu,\boldsymbol\Theta}\big[\|\widehat\boldsymbol\mu(\mathbf Y)-\boldsymbol\mu\|_2^2\big]
}_{\text{\rm risk in our model \eqref{definition_observation}}}\bigg].

On the other side,
it has been established in \citep{Gao2015} that the minimax rate of estimating
$\boldsymbol\mu$ in Huber's contamination model is
\begin{align}
r^{\rm all}_{\rm mmx}({n,p,s}) = \sigma^2\Big(\frac{p}{n}\vee \frac{s^2}{n^2}\Big).    
\end{align}

The best known
computationally tractable robust estimator, the element-wise median, 
has a rate of order \citep[Prop.\ 2.1]{Gao2015}
\begin{align}
\sigma^2\Big(\frac{p}{n}\vee \frac{s^2p}{n^2}\Big).    
\end{align}

We define the group-lasso estimator by
\begin{align} (\widehat\boldsymbol\mu,\widehat\mathbf\Theta) \in \arg\min_{\boldsymbol{m},\mathbf{T}}
\Big\{ \sum_{i=1}^n \| \boldsymbol Y\!_i -\boldsymbol{m} - \boldsymbol{t}_i \|_2^2 + \sum_{i=1}^n \lambda_i \|\boldsymbol{t}_i\|_2 \Big\}.
\end{align}
where the $\lambda_i$ are some positive numbers to be defined later.

First, using the fact that 
$\mathbf\Pi\boldsymbol{t}^j = \boldsymbol{t}^j - (\mathbf I_n-\mathbf\Pi)\boldsymbol{t}^j$, we get 
$\|\mathbf\Pi(\boldsymbol Y\!^j-\boldsymbol{t}^j) \|_2^2 = \|\mathbf\Pi\boldsymbol Y\!^j-\boldsymbol{t}^j \|_2^2 -
(\nicefrac1n) \big(\mathbf 1_n^\top\boldsymbol{t}^j\big)^2$, so that
\begin{equation}
	\widehat{\mathbf\Theta} \in \arg\min \Big\{ \sum_{i=1}^n \| (\mathbf Y\mathbf\Pi)_i-\boldsymbol{t}_i \|_2^2 - \frac1n \Big\| \sum_{i=1}^n \boldsymbol{t}_i \Big\|_2^2 + \sum_{i=1}^n \lambda_i \|\boldsymbol{t}_i\|_2 \Big\}.
\end{equation}
Recall that $\boldsymbol L_n(\boldsymbol\Theta) = (\nicefrac1n) \boldsymbol L(\boldsymbol\Theta)$. The first-order necessary 
conditions imply that, for every $i$ such that $\widehat{\boldsymbol\theta}_i\neq\mathbf 0_p$,
\begin{equation}
	-2\big( (\mathbf Y\mathbf\Pi)_i-\widehat{\boldsymbol\theta}_i \big) - 2 \boldsymbol L_n(\widehat{\boldsymbol\Theta}) + \frac{\lambda_i \widehat{\boldsymbol\theta}_i}{\|\widehat{\boldsymbol\theta}_i\|_2} =\mathbf  0_p.
\end{equation}
Furthermore, $\widehat\boldsymbol\theta_i=\mathbf 0_p$ if and only if
$\big\|2 (\mathbf Y\mathbf\Pi)_i+ 2\boldsymbol L_n(\widehat{\boldsymbol\Theta}) \big\|_2\le \lambda_i$. 
We infer that
\begin{equation}
	\widehat{\boldsymbol\theta}_i = \frac{(\mathbf Y\mathbf\Pi)_i+\boldsymbol L_n(\widehat{\boldsymbol\Theta}) }{\big\|(\mathbf Y\mathbf\Pi)_i+
	\boldsymbol L_n(\widehat{\boldsymbol\Theta}) \big\|_2}~\Big( \big\|(\mathbf Y\mathbf\Pi)_i+\boldsymbol L_n(\widehat\boldsymbol\Theta) \big\|_2 - \frac{\lambda_i}2 \Big)_+
\end{equation}
for every $i$. Finally, denoting $\boldsymbol Z_i=(\mathbf Y\mathbf\Pi)_i+\boldsymbol L_n(\widehat{\boldsymbol\Theta})$,  we get
\begin{equation} \widehat{\boldsymbol\theta}_i = \boldsymbol Z_i \Big( 1-\frac{\lambda_i}{2\|\boldsymbol Z_i \|_2} \Big)_+.
\end{equation}

\setstretch{1.2}
\SetAlgoLined
\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}\SetKwInOut{Parameter}{parameters}
\Input{matrix $\mathbf Y$, noise variance $\sigma$, number of outliers $s$.}
\Parameter{number of iterations $N$, confidence level $\delta$.}
\Output{vectors $\widehat\boldsymbol L_n{\!\!\!}^{\rm IST}$ and $\widehat\boldsymbol\mu^{\rm IST}$.}
initialization\; 
\qquad $\widehat\boldsymbol\Theta \gets $ solution of \eqref{definition_groupestimator} with 
$\lambda^2 = 32\sigma^2(p+8\log(n/\delta))$\;
\qquad $\epsilon\gets  \sqrt{288}\,\displaystyle\frac{s\lambda}{n\sigma}$\;
\For{$k=1,\ldots,N$}{
Set $\widehat\boldsymbol L_n \gets \boldsymbol L_n(\widehat\boldsymbol\Theta)$\;
Set $\gamma^2\gets 8\epsilon^2+4\sqrt{4\epsilon^4+p\epsilon^2}$\;
\For{$i=1,\ldots,n$}{
Set $\boldsymbol Z_i \gets (\mathbf Y\mathbf\Pi)_i+\widehat\boldsymbol L_n$\;
Set 
$\displaystyle
\boldsymbol\theta_i \gets \boldsymbol Z_i\bigg(1-\frac{\sigma\gamma}{(\|\boldsymbol Z_i\|_2^2-
\frac{n-1}{n}\sigma^2 p)^{1/2}_+}\bigg)_+.
$
}
{
update\;
\qquad $\widehat\boldsymbol\Theta \gets [\widehat\boldsymbol\theta_1,\ldots,\widehat\boldsymbol\theta_n]$.\;
\qquad $\epsilon\gets \nicefrac{4}{n}(\,s\gamma+ s + \sqrt{sp} + 
\{2s\log(4/\delta)\}^{1/2})$\;
}
}
\Return{$\widehat\boldsymbol L{}^{\rm IST}_n\gets \boldsymbol L_n(\widehat\boldsymbol\Theta)$ and 
$\widehat\boldsymbol\mu{}^{\rm IST}=\boldsymbol L_n(\mathbf Y)-\widehat\boldsymbol L{}^{\rm IST}_n$.} 
\caption{Iterative Soft Thresholding}

Let us set $\boldsymbol Z_i = (\mathbf Y\mathbf\Pi)_i+\widetilde\boldsymbol L_n$, where $\widetilde\boldsymbol L_n$ is a
	preliminary estimator of $\boldsymbol L_n(\boldsymbol\Theta)$. Let $\delta\in(0,1)$ be a tolerance level.
	Consider the estimator of $\mathbf\Theta$ defined by concatenating the vectors
	\begin{align} \widehat\boldsymbol\theta_i = \boldsymbol Z_i \bigg(1-\frac{\sigma\gamma}{(\|\boldsymbol Z_i\|_2^2-\frac{n-1}{n}
	\sigma^2 p)_+^{1/2}}\bigg)_+,
	\end{align}
	where $\gamma^2 > 4\log(4n/\delta)+4 \{p\log(4n/\delta)\}^{1/2}$ is a tuning parameter.
	Define the event
	\begin{align}
	\Omega_1 &= \Bigg\{\|\widetilde\boldsymbol L_n-\boldsymbol L_n(\boldsymbol\Theta)\|_2	< 
	\frac{\sigma\gamma^2}{4\sqrt{p+\gamma^2}}\Bigg\}.
	\end{align}
	There is an event $\bar\Omega$ (the same for all estimators $\widetilde\boldsymbol L_n$) of probability 
	at least $1-\delta$, such that on $\Omega_1\cap\bar\Omega$, we have
	\begin{align}
		\|\boldsymbol L(\widehat{\boldsymbol\Theta}-\boldsymbol\Theta) \|_2
		\le 4\sigma\Big(\,s\gamma+ s + \sqrt{sp} +  \{2s\log(4/\delta)\}^{1/2}\Big). \end{align}

If $\epsilon_0^2\le p$, $n\ge 33s$ and $a\le 0.5\sqrt{p}$, then
\begin{align} \epsilon_k \le  \Big\{p^{1/2}\Big(\frac{33^2 s^2}{n^2}\Big)^{1-(\nicefrac12)^{k}}\Big\}
\vee 2a.
\end{align}

assumptions:
if the condition
\begin{align}
s\le c_1 n
\end{align}
is satisfied

nodes.statement:
Using the triangle inequality several times, we get
\begin{align}
\|\widehat\boldsymbol L{}^{\rm GSS}-\boldsymbol L(\mathbf\Theta)\|_2
    &\le \|\boldsymbol L(\mathbf Y_{\widehat S})-\boldsymbol L(\mathbf Y_{S})\|_2+ \|\boldsymbol L(\mathbf Y_{S})- \boldsymbol L(\mathbf\Theta_S)\|_2\\
    &\le \|\boldsymbol L(\mathbf Y_{\widehat S\setminus S})\|_2+\|\boldsymbol L(\mathbf Y_{S\setminus \widehat S})\|_2
			+ \sigma\|\boldsymbol L(\boldsymbol\xi_{S})\|_2 \phantom{\Big(}\\
    &\le \sigma\|\boldsymbol L(\boldsymbol\xi_{\widehat S\setminus S})\|_2+\|\boldsymbol L(\mathbf Y_{S\setminus \widehat S})\|_2
			+ \sigma\|\boldsymbol L(\boldsymbol\xi_{S})\|_2. \end{align}
To upper bound the three terms of the right hand side, we introduce the event
\begin{equation}
\Omega_\lambda = \Big\{\|\boldsymbol L(\boldsymbol\xi_J) \|_2^2\le 2|J|(p+\lambda |J|)\text{ for all }
J\subseteq [n]\Big\}.
\end{equation}
We will show that the following three claims are true for the tuning parameter $\lambda$ chosen as in the statement of the theorem.
\begin{description}\itemsep=5pt
\item[Claim 1:] On the event $\Omega_\lambda$, at least half of the elements of each $\widehat J_\ell$
belong to the true sparsity pattern $S$. Thus $|\widehat S|\le 2s$.
\item[Claim 2:] $\|\boldsymbol L(\mathbf Y_{S\setminus\widehat S})\|_2^2\le 12\sigma^2 s(p+\lambda s)$.
\item[Claim 3:] The probability of $\Omega_\lambda$ is close to $1$.
\end{description}
Let us first show that these claims imply the claim of the theorem. Indeed,  the second term of the right hand side of \eqref{line:3} is bounded by $\sigma\sqrt{12s(p+\lambda s)}$ in view of Claim 2. The third term is bounded by $\sigma\sqrt{2s(p+\lambda s)}$ on the event $\Omega_\lambda$. Concerning the first term, we know that on $\Omega_\lambda$ it is bounded by $\sigma\sqrt{2|\widehat S|(p+\lambda |\widehat S|)}$. In view of Claim 1, $|\widehat S|\le 2s$. All these inequalities imply that
\begin{align}
\|\widehat\boldsymbol L{}^{\rm GSS}-\boldsymbol L(\mathbf\Theta)\|_2^2
    &\le 60\sigma^2{s(p+\lambda s)}
\end{align}
on the event $\Omega_\lambda$. This is exactly the claim of the theorem.

Let us prove now Claims 1-3. To prove the first claim, let us assume that there is a set $J$ among $\widehat J_1,\ldots,\widehat J_\ell$ and a subset $J_0\subset J$ of cardinality\footnote{To avoid uninteresting and irrelevant technicalities, we assume here that $|J|$ is even.} $|J|/2$ such that $J_0\subset S^c$. This readily implies that $\|\boldsymbol L(\mathbf Y_{J})\|_2^2\ge 12\sigma^2 |J|(p+\lambda |J|)$ and $\|\boldsymbol L(\mathbf Y_{J\setminus J_0})\|_2^2< 6\sigma^2 |J|(p+\lambda |J|/2)$. Using the additivity of $\boldsymbol L$ and the triangle inequality, we get
\begin{align}
\|\boldsymbol L(\mathbf Y_{J})\|_2^2
    & \le (\|\boldsymbol L(\mathbf Y_{J\setminus J_0})\|_2+ \sigma\|\boldsymbol L(\boldsymbol\xi_{J_0})\|_2)^2 \phantom{\frac32} \\
    & \le \frac32\|\boldsymbol L(\mathbf Y_{J\setminus J_0})\|_2^2+ 3\sigma^2\|\boldsymbol L(\boldsymbol\xi_{J_0})\|_2^2\\
    & < 9\sigma^2 |J|(p+\lambda |J|/2)+ 3\sigma^2 |J|(p+\lambda|J|/2) \phantom{\frac32}\\
    & < 12\sigma^2 |J|(p+\lambda|J|). \phantom{\frac32}
\end{align}
This is in contradiction with the fact that $J$ is one of the sets $\widehat J_1,\ldots,\widehat J_L$. So, Claim 1 is proved.

The proof of Claim 2 is simpler. By construction, the set $S\setminus \widehat S$ is a subset of $I_L$, where $L$ is the number of steps performed by the algorithm. Since the algorithm terminated after the $L$th step, this means that $\mathcal I$ was empty, which implies  that $\|\boldsymbol L(\mathbf Y_{S\setminus\widehat S})\|_2^2\le 12\sigma^2 |S\setminus\widehat S|(p+\lambda|S\setminus\widehat S|) \le 12\sigma^2 s(p+\lambda s)$.

It remains to prove Claim 3. This can be done using the union bound and tail bounds for $\chi^2_p$-distributed random variables. Indeed, we have
\begin{align}
\mathbf P_\mathbf\Theta\big(\Omega_\lambda^c\big)
    &\le \sum_{k=1}^n \mathbf P_\mathbf\Theta\big(\exists J\subset [n]\text{ s.t. } |J|=k\text{ and }
            \|\boldsymbol L(\boldsymbol\xi_J)\|_2^2> 2|J|(p+\lambda|J|)\big)\\
    &\le \sum_{k=1}^n {{n}\choose{k}} \max_{J:|J|=k}
            \mathbf P_\mathbf\Theta\big(\|\boldsymbol L(\boldsymbol\xi_J)\|_2^2> 2k(p+\lambda k)\big)\\
    &\le \sum_{k=1}^n {{n}\choose{k}}
            \mathbf P\big(\eta > 2p + 2 \lambda k\big)
\end{align}
where $\eta\sim \chi^2_p$. Using the well known bound on the tails of the $\chi^2_p$
distribution, we get
\begin{align}
\mathbf P\big(\Omega_\lambda^c\big)
    &\le \sum_{k=1}^n {{n}\choose{k}} e^{-2\lambda k/3} = (1+e^{-2\lambda/3})^n-1.
\end{align}
Therefore, for $\lambda = \nicefrac32\log(\nicefrac{2n}{\delta})$, we obtain that  $\mathbf P_\mathbf\Theta\big(\Omega_\lambda^c\big)\le \delta$. This completes the proof of Claim~3 and of the theorem.

\mathbf P_\mathbf\Theta\big(\Omega_\lambda^c\big)
    &\le \sum_{k=1}^n \mathbf P_\mathbf\Theta\big(\exists J\subset [n]\text{ s.t. } |J|=k\text{ and }
            \|\boldsymbol L(\boldsymbol\xi_J)\|_2^2> 2|J|(p+\lambda|J|)\big)\\
    &\le \sum_{k=1}^n {{n}\choose{k}} \max_{J:|J|=k}
            \mathbf P_\mathbf\Theta\big(\|\boldsymbol L(\boldsymbol\xi_J)\|_2^2> 2k(p+\lambda k)\big)\\
    &\le \sum_{k=1}^n {{n}\choose{k}}
            \mathbf P\big(\eta > 2p + 2 \lambda k\big)

Recall that $\boldsymbol\Xi =(\boldsymbol\xi_1, \ldots,\boldsymbol\xi_n)$. First, we decompose
	\begin{align}
		\widehat{\boldsymbol L}{}^{\rm GHT}-\boldsymbol L(\mathbf\Theta)
		&= \boldsymbol L(\boldsymbol Y\!_S-\boldsymbol\Theta) - \boldsymbol L(\boldsymbol Y\!_{S\setminus S_\lambda} )+ \boldsymbol L(\boldsymbol Y\!_{S_\lambda\setminus S})\\
		&= \sigma\boldsymbol L(\boldsymbol\Xi_S) - \boldsymbol L(\boldsymbol Y\!_{S\setminus S_\lambda} )+ \sigma\boldsymbol L(\boldsymbol\Xi_{S_\lambda\setminus S})\\
		&= \sigma\boldsymbol L(\boldsymbol\Xi_{S\cap S_\lambda}) - \boldsymbol L(\boldsymbol\Theta_{S\setminus S_\lambda} )+ \sigma\boldsymbol L(\boldsymbol\Xi_{S_\lambda\setminus S}). \end{align}
	so that
	\begin{align} \big\| \widehat{\boldsymbol L}{}^{\rm GHT}-\boldsymbol L(\mathbf\Theta) \big\|_2 &\le \sigma\|\boldsymbol L(\boldsymbol\Xi_{S\cap S_\lambda})\|_2 +
	\|\boldsymbol L(\boldsymbol\Theta_{S\setminus S_\lambda})\|_2 + \sigma\|\boldsymbol L(\boldsymbol\Xi_{S_\lambda \setminus S})\|_2.
	\end{align}
	The first term corresponds to the stochastic error of estimating the signal vectors   
	that are correctly identified as nonzero. We can write
	\begin{equation}
	\|\boldsymbol L(\boldsymbol\Xi_{S\cap S_\lambda})\|_2 = \|\boldsymbol\Xi_{S}\mathbf 1_{S\cap S_\lambda}\|_2\le
 	\sqrt{s}\|\boldsymbol\Xi_{S}\|.
	\end{equation}
	The second-order moment of the spectral norm of the random matrix $\boldsymbol\Xi_S$ can be
	evaluated using well-known upper bounds on the spectral norm of matrices with
	independent Gaussian entries, recalled in \Cref{lemma_Wishart2} below, so that
	\begin{equation} \mathbf E_\mathbf\Theta \big[\|\boldsymbol L(\boldsymbol\Xi_{S\cap S_\lambda})\|_2^2\big] \le 3s^2 + 3sp+12s.
	\end{equation}
 	Set $\eta_i=\boldsymbol\theta_i^\top\boldsymbol\xi_i/\|\boldsymbol\theta_i\|_2$. We can control the second term in \eqref{ineq:2} using the following inequality
    \begin{align}
	\|\boldsymbol L(\boldsymbol\Theta_{S\setminus S_\lambda})\|_2&\le \sum_{i\in S} \|\boldsymbol\theta_i\|_2 \mathds{1}_{\|\boldsymbol\theta_i\|^2<\lambda^2	-2\sigma\boldsymbol\theta_i^\top \boldsymbol\xi_i-\sigma^2\|\boldsymbol\xi_i\|^2} \\
