\mathbf P\big(\Omega_\lambda^c\big)
    &\le \sum_{k=1}^n {{n}\choose{k}} e^{-2\lambda k/3} = (1+e^{-2\lambda/3})^n-1.
\end{align}
Therefore, for $\lambda = \nicefrac32\log(\nicefrac{2n}{\delta})$, we obtain that  $\mathbf P_\mathbf\Theta\big(\Omega_\lambda^c\big)\le \delta$. This completes the proof of Claim~3 and of the theorem.

Indeed, we have
\begin{align}
\mathbf P_\mathbf\Theta\big(\Omega_\lambda^c\big)
    &\le \sum_{k=1}^n \mathbf P_\mathbf\Theta\big(\exists J\subset [n]\text{ s.t. } |J|=k\text{ and }
            \|\boldsymbol L(\boldsymbol\xi_J)\|_2^2> 2|J|(p+\lambda|J|)\big)\\
    &\le \sum_{k=1}^n {{n}\choose{k}} \max_{J:|J|=k}
            \mathbf P_\mathbf\Theta\big(\|\boldsymbol L(\boldsymbol\xi_J)\|_2^2> 2k(p+\lambda k)\big)\\
    &\le \sum_{k=1}^n {{n}\choose{k}}
            \mathbf P\big(\eta > 2p + 2 \lambda k\big)
\end{align}
where $\eta\sim \chi^2_p$.

Using the well known bound on the tails of the $\chi^2_p$
distribution, we get
\begin{align}
\mathbf P\big(\Omega_\lambda^c\big)
    &\le \sum_{k=1}^n {{n}\choose{k}} e^{-2\lambda k/3} = (1+e^{-2\lambda/3})^n-1.
\end{align}

First, we decompose
	\begin{align}
		\widehat{\boldsymbol L}{}^{\rm GHT}-\boldsymbol L(\mathbf\Theta)
		&= \boldsymbol L(\boldsymbol Y\!_S-\boldsymbol\Theta) - \boldsymbol L(\boldsymbol Y\!_{S\setminus S_\lambda} )+ \boldsymbol L(\boldsymbol Y\!_{S_\lambda\setminus S})\\
		&= \sigma\boldsymbol L(\boldsymbol\Xi_S) - \boldsymbol L(\boldsymbol Y\!_{S\setminus S_\lambda} )+ \sigma\boldsymbol L(\boldsymbol\Xi_{S_\lambda\setminus S})\\
		&= \sigma\boldsymbol L(\boldsymbol\Xi_{S\cap S_\lambda}) - \boldsymbol L(\boldsymbol\Theta_{S\setminus S_\lambda} )+ \sigma\boldsymbol L(\boldsymbol\Xi_{S_\lambda\setminus S}). \end{align}
	so that
	\begin{align} \big\| \widehat{\boldsymbol L}{}^{\rm GHT}-\boldsymbol L(\mathbf\Theta) \big\|_2 &\le \sigma\|\boldsymbol L(\boldsymbol\Xi_{S\cap S_\lambda})\|_2 +
	\|\boldsymbol L(\boldsymbol\Theta_{S\setminus S_\lambda})\|_2 + \sigma\|\boldsymbol L(\boldsymbol\Xi_{S_\lambda \setminus S})\|_2.
	\end{align}

Set $\eta_i=\boldsymbol\theta_i^\top\boldsymbol\xi_i/\|\boldsymbol\theta_i\|_2$. We can control the second term in \eqref{ineq:2} using the following inequality
    \begin{align}
	\|\boldsymbol L(\boldsymbol\Theta_{S\setminus S_\lambda})\|_2&\le \sum_{i\in S} \|\boldsymbol\theta_i\|_2 \mathds{1}_{\|\boldsymbol\theta_i\|^2<\lambda^2	-2\sigma\boldsymbol\theta_i^\top \boldsymbol\xi_i-\sigma^2\|\boldsymbol\xi_i\|^2} \\
	&\le s(\lambda^2-\sigma^2p)^{1/2}+2\sigma\sum_{i\in S} |\eta_i| + \sigma\sum_{i\in S} \big| \|\boldsymbol\xi_i\|^2-p\, \big|^{1/2}.
	\end{align}
	This readily yields
	\begin{equation} \mathbf E_\mathbf\Theta \big[\|\boldsymbol L(\boldsymbol\Theta_{S\setminus S_\lambda})\|_2^2]^{1/2}
	\le s(\lambda^2-\sigma^2p)^{1/2}+2\sigma s + \sigma s (2p)^{1/4}.
	\end{equation}

The third term in \eqref{ineq:2}
	corresponds to the Type II error in the problem of support estimation. Denoting
	$t=(\lambda^2-\sigma^2p)/\sigma^2$, and using tail bounds for the chi-squared
	random variables (see \Cref{lemme_esperancechideux} below), we get
	\begin{align}
	\mathbf E_\mathbf\Theta[\|\boldsymbol\Xi_{S_\lambda \setminus S}\|_2^2]
	    &= \mathbf E_\mathbf\Theta\bigg[\bigg\| \sum_{i\in S^c} \boldsymbol\xi_i\mathds{1}(\|\boldsymbol\xi_i\|_2\ge \lambda/\sigma)\bigg\|_2^2\bigg]\\
	    &= \sum_{i\in S^c}\mathbf E_\mathbf\Theta[\|\boldsymbol\xi_i\|_2^2\mathds{1}(\|\boldsymbol\xi_i\|_2^2\ge p+t)]\\
	    &\le 	2n \big( pe^{-t^2/32p}\,\mathds{1}_{t< 4p} + t
	    e^{-t/4}\mathds{1}_{t \ge 4p}\big).
	\end{align}
	Using the fact that $t= 4\log(1+n/s^2)\vee\big\{16p\log(1+n^2p/s^4)\big\}^{1/2}$
	we arrive at
	\begin{align}
	\mathbf E_\mathbf\Theta[\|\boldsymbol\Xi_{S_\lambda \setminus S}\|_2^2]
	    &\le 	\Big(8s^2\log(1+n/s^2)\Big)\vee \Big(2s^2\sqrt{p}
			\wedge 2np\Big).
	\end{align}

In the other case, $\lambda^2< \sigma^2 p + \sigma^2\sqrt{p}$, we consider the first term:
	\begin{align}
	\mathbf E_\mathbf\Theta \big[\big\|  \boldsymbol L(\boldsymbol\Xi_{S_\lambda\setminus S})\big\|_2^2\big] 
		&= (n-s)p - (n-s)\mathbf E [\|\boldsymbol\xi_1\|_2^2 \mathds{1}_{\|\boldsymbol\xi_1\|_2\le\lambda/\sigma}] \\
		&\ge (n-s)p - (n-s)(p+\sqrt{p}) \mathbf P\big(\|\boldsymbol\xi_1\|_2^2-p\le\sqrt{p}\big).
	\end{align}
	The probability in the right-hand side converges to $\Phi(2^{-1/2})\le 0.8$, 
	so that for $p\ge 64$ and $s\le n/2$, we have
	\begin{equation}
	\mathbf E_\mathbf\Theta \big[\big\|  \boldsymbol L(\boldsymbol\Xi_{S_\lambda\setminus S})\big\|_2^2\big] 
	\ge (n-s) (0.2p-0.8p^{1/2}) \ge 0.05 np.
	\end{equation}

In the other case, $\lambda^2< \sigma^2 p + \sigma^2\sqrt{p}$, we consider the first term:
	\begin{align}
	\mathbf E_\mathbf\Theta \big[\big\|  \boldsymbol L(\boldsymbol\Xi_{S_\lambda\setminus S})\big\|_2^2\big] 
		&= (n-s)p - (n-s)\mathbf E [\|\boldsymbol\xi_1\|_2^2 \mathds{1}_{\|\boldsymbol\xi_1\|_2\le\lambda/\sigma}] \\
		&\ge (n-s)p - (n-s)(p+\sqrt{p}) \mathbf P\big(\|\boldsymbol\xi_1\|_2^2-p\le\sqrt{p}\big).
	\end{align}

The probability in the right-hand side converges to $\Phi(2^{-1/2})\le 0.8$, 
	so that for $p\ge 64$ and $s\le n/2$, we have
	\begin{equation}
	\mathbf E_\mathbf\Theta \big[\big\|  \boldsymbol L(\boldsymbol\Xi_{S_\lambda\setminus S})\big\|_2^2\big] 
	\ge (n-s) (0.2p-0.8p^{1/2}) \ge 0.05 np.
	\end{equation}

Finally, according to \eqref{esperance_norm}, we have for $p$ large enough
	\begin{align}
		\mathbf E_\mathbf\Theta \big[\|\boldsymbol L(\boldsymbol\Xi_{S\cap S_\lambda})\|_2^2\big] \le 3s^2 + 3sp+12s
		\le \frac{s^2\sqrt{p}}{65} + 3sp
	\end{align}	
	so that
	\begin{equation}
	\mathbf E_\mathbf\Theta \big[\big\| \widehat{\boldsymbol L}{}^{\rm GHT}-\boldsymbol L(\mathbf\Theta) \big\|_2^2\big] 
	\ge \frac{s^2\sqrt{p}}{65}\wedge(0.05np) - 3sp.
	\end{equation}

\paragraph{Evaluation of the approximation error}
For the first term, we use the Minkowski inequality as follows
	\begin{align} \|T_1\|_{L_2}\le \Big\|\sum_{i\in S} \boldsymbol\theta_i \mathds{1}_{\|\boldsymbol Y\!_i\|_2^2\le\sigma^2 (p+\gamma^2)
	}\Big\|_{L_2} + \sigma\Big\|\sum_{i\in S}  \boldsymbol\theta_i \frac{\gamma\,\mathds{1}_{\|\boldsymbol Y\!_i\|_2^2>\sigma^2 
	(p+\gamma^2)}}{\big(\|\boldsymbol Y\!_i\|^2_2-\sigma^2p\big)^{1/2}}\Big\|_{L_2}.
	\end{align}
	The first part can be treated exactly as in \eqref{eval_on_support} of the proof 
	of~\Cref{theorem_HT}, \textit{i.e., }
	\begin{equation} \Big\|\sum_{i\in S} \boldsymbol\theta_i \mathds{1}_{\|\boldsymbol Y\!_i\|_2^2\le\sigma^2 (p+\gamma^2)
	}\Big\|_{L_2} \le \sigma s \big(\gamma+2 +  (2p)^{1/4}\big).
	\end{equation}
	For assessing the second term in the right hand side of \eqref{eqT1}, 
	we set 
	\begin{align}
	T_{1,i} = \frac{\|\boldsymbol\theta_i\|_2\gamma\,\mathds{1}_{\|\boldsymbol Y\!_i\|_2^2>\sigma^2 (p+\gamma^2)}}
	{(\|\boldsymbol\theta_i\|^2_2+2\sigma\boldsymbol\theta_i^\top\boldsymbol\xi_i+\sigma^2\big(\|\boldsymbol\xi_i\|_2^2-p\big))^{1/2}} .
	\end{align}
	We consider two cases. The first case corresponds to 
	$\big|2\sigma\boldsymbol\theta_i^\top\boldsymbol\xi_i+\sigma^2\big(\|\boldsymbol\xi_i\|_2^2-p\big)\big|<\|\boldsymbol\theta_i\|_2^2/2$. 
	In this case one easily checks that  $T_{1,i}\le \sqrt{2}\,\gamma$. In the second case, 
	$\big|2\sigma\boldsymbol\theta_i^\top\boldsymbol\xi_i+\sigma^2\big(\|\boldsymbol\xi_i\|_2^2-p\big)\big|\ge\|\boldsymbol\theta_i\|_2^2/2$, 
	we have 
	\begin{equation}
		\|\boldsymbol\theta_i\|_2^2/4 \le 2\sigma|\boldsymbol\theta_i^\top\boldsymbol\xi_i| \quad \text{or} \quad \|\boldsymbol\theta_i\|_2^2/4 \le 
		\sigma^2\big|\|\boldsymbol\xi_i\|_2^2-p\big|.
	\end{equation}
	This readily implies that 
	\begin{equation}
		T_{1,i}= \frac{\|\boldsymbol\theta_i\|\gamma\,\mathds{1}_{\|\boldsymbol Y\!_i\|_2^2>\sigma^2 (p+\gamma^2)}}
	  {\big(\|\boldsymbol Y\!_i\|^2_2-\sigma^2p\big)^{1/2}}\le \|\boldsymbol\theta_i\| \le 8\sigma 
		\frac{|\boldsymbol\theta_i^\top\boldsymbol\xi_i|}{\|\boldsymbol\theta_i\|_2}+ 2\sigma\sqrt{|\|\boldsymbol\xi_i\|_2^2-p|}.
	\end{equation}
	Therefore, using the fact that $\mathbf E[|\boldsymbol\theta_i^\top\boldsymbol\xi_i|^2] = \|\boldsymbol\theta_i\|_2^2$ 
	and $\mathbf E[|\|\boldsymbol\xi_i\|_2^2-p|^2] = 2p$, we get	
	\begin{equation}
		\|T_{1,i}\|_{L_2} \le 8\sigma + 2\sigma (2p)^{1/4}.
	\end{equation}
	Combining this inequality with \eqref{eqT1} and \eqref{eqT1a}, we arrive at
	\begin{align}
		\|T_1\|_{L_2} &\le \sigma 
		s\gamma+2\sigma s + \sigma s(2p)^{1/4} + 8\sigma s+ 2\sigma s(2p)^{1/4}\\
		&= \sigma s\gamma+10\sigma s + 3\sigma s(2p)^{1/4}. \end{align}

\paragraph{Evaluation of the approximation error}
For the first term, we use the Minkowski inequality as follows
	\begin{align} \|T_1\|_{L_2}\le \Big\|\sum_{i\in S} \boldsymbol\theta_i \mathds{1}_{\|\boldsymbol Y\!_i\|_2^2\le\sigma^2 (p+\gamma^2)
	}\Big\|_{L_2} + \sigma\Big\|\sum_{i\in S}  \boldsymbol\theta_i \frac{\gamma\,\mathds{1}_{\|\boldsymbol Y\!_i\|_2^2>\sigma^2 
	(p+\gamma^2)}}{\big(\|\boldsymbol Y\!_i\|^2_2-\sigma^2p\big)^{1/2}}\Big\|_{L_2}.
	\end{align}

The first part can be treated exactly as in \eqref{eval_on_support} of the proof 
	of~\Cref{theorem_HT}, \textit{i.e., }
	\begin{equation} \Big\|\sum_{i\in S} \boldsymbol\theta_i \mathds{1}_{\|\boldsymbol Y\!_i\|_2^2\le\sigma^2 (p+\gamma^2)
	}\Big\|_{L_2} \le \sigma s \big(\gamma+2 +  (2p)^{1/4}\big).
	\end{equation}

For assessing the second term in the right hand side of \eqref{eqT1}, 
	we set 
	\begin{align}
	T_{1,i} = \frac{\|\boldsymbol\theta_i\|_2\gamma\,\mathds{1}_{\|\boldsymbol Y\!_i\|_2^2>\sigma^2 (p+\gamma^2)}}
	{(\|\boldsymbol\theta_i\|^2_2+2\sigma\boldsymbol\theta_i^\top\boldsymbol\xi_i+\sigma^2\big(\|\boldsymbol\xi_i\|_2^2-p\big))^{1/2}} .
	\end{align}

In the second case, 
	$\big|2\sigma\boldsymbol\theta_i^\top\boldsymbol\xi_i+\sigma^2\big(\|\boldsymbol\xi_i\|_2^2-p\big)\big|\ge\|\boldsymbol\theta_i\|_2^2/2$, 
	we have 
	\begin{equation}
		\|\boldsymbol\theta_i\|_2^2/4 \le 2\sigma|\boldsymbol\theta_i^\top\boldsymbol\xi_i| \quad \text{or} \quad \|\boldsymbol\theta_i\|_2^2/4 \le 
		\sigma^2\big|\|\boldsymbol\xi_i\|_2^2-p\big|.
	\end{equation}
	This readily implies that 
	\begin{equation}
		T_{1,i}= \frac{\|\boldsymbol\theta_i\|\gamma\,\mathds{1}_{\|\boldsymbol Y\!_i\|_2^2>\sigma^2 (p+\gamma^2)}}
	  {\big(\|\boldsymbol Y\!_i\|^2_2-\sigma^2p\big)^{1/2}}\le \|\boldsymbol\theta_i\| \le 8\sigma 
		\frac{|\boldsymbol\theta_i^\top\boldsymbol\xi_i|}{\|\boldsymbol\theta_i\|_2}+ 2\sigma\sqrt{|\|\boldsymbol\xi_i\|_2^2-p|}.
	\end{equation}

Therefore, using the fact that $\mathbf E[|\boldsymbol\theta_i^\top\boldsymbol\xi_i|^2] = \|\boldsymbol\theta_i\|_2^2$ 
	and $\mathbf E[|\|\boldsymbol\xi_i\|_2^2-p|^2] = 2p$, we get	
	\begin{equation}
		\|T_{1,i}\|_{L_2} \le 8\sigma + 2\sigma (2p)^{1/4}.
	\end{equation}

Combining this inequality with \eqref{eqT1} and \eqref{eqT1a}, we arrive at
	\begin{align}
		\|T_1\|_{L_2} &\le \sigma 
		s\gamma+2\sigma s + \sigma s(2p)^{1/4} + 8\sigma s+ 2\sigma s(2p)^{1/4}\\
		&= \sigma s\gamma+10\sigma s + 3\sigma s(2p)^{1/4}. \end{align}

\paragraph{Evaluation of the stochastic error on $S$} 
	The second term can be treated
	exactly as in the proof of Theorem~\ref{theorem_HT} using Wishart matrices, \textit{i.e., }
	\begin{equation}
	\|T_2\|_{L_2}^2 \le \sigma^2 s\mathbf E[\|\boldsymbol\Xi_S\|^2] \le \sigma^2(3s^2+3sp+12s).
	\end{equation}

We conclude by~\Cref{lemme_esperancechideux} that the last term satisfies
	\begin{equation}
		\|T_3\|_{L_2}^2\le 
		2n\sigma^2  \big( pe^{-\gamma^4/32p}\,\mathds{1}_{\gamma^2< 4p} +
		\gamma^2e^{-\gamma^2/4}\mathds{1}_{\gamma^2\ge 4p}\big).
	\end{equation}

Using the fact that $\gamma^2= 4\log(1+n/s^2)\vee\big\{16p\log(1+n^2p/s^4)
	\big\}^{1/2}$ we arrive at
	\begin{align}
	\|T_3\|_{L_2}^2
	    &\le \sigma^2	\Big(8s^2\log(1+n/s^2)\Big)\vee \Big(2s^2\sqrt{p}
			\wedge 2np\Big).
