This completes the proof of the theorem.

Now, if $60\widehat s(p+\lambda \widehat s)\le 2np+3n\log(2/\delta)$, then
$\widehat\boldsymbol L{}^{\rm adGSS}=\widehat\boldsymbol L{}^{\rm GSS}$ and we have
\begin{align}
    \|\widehat\boldsymbol L{}^{\rm adGSS}-\boldsymbol L(\boldsymbol\Theta)\|_2 =  \|\widehat\boldsymbol L{}^{\rm GSS}-\boldsymbol L(\boldsymbol\Theta)\|_2 \le r_2
\end{align}
along with
\begin{align}
    \|\widehat\boldsymbol L{}^{\rm adGSS}-\boldsymbol L(\boldsymbol\Theta)\|_2
        &=  \|\widehat\boldsymbol L{}^{\rm GSS}-\boldsymbol L(\mathbf Y)\|_2 +\|\boldsymbol L(\mathbf Y)-\boldsymbol L(\boldsymbol\Theta)\|_2\\
        &\le \{\sigma\sqrt{60\widehat s(p+\lambda\widehat s)}+ r_1\} +r_1\le 3r_1.
\end{align}
Thus, $\|\widehat\boldsymbol L{}^{\rm adGSS}-\boldsymbol L(\boldsymbol\Theta)\|_2 \le 3 (r_1\wedge r_2)$.

In view of~\eqref{definition_groupestimator}, we have
	\begin{equation}
	\big\| (\boldsymbol\Theta-\widehat{\boldsymbol\Theta})\mathbf\Pi + \sigma\boldsymbol\Xi\mathbf\Pi \big\|_F^2 + \lambda \sum_{i=1}^n \|\widehat\boldsymbol\theta_i\|_2 \le \sigma^2 \| \boldsymbol\Xi\mathbf\Pi \|_F^2 + \lambda \sum_{i=1}^n \|\boldsymbol\theta_i\|_2.
	\end{equation}

Developing the left-hand side, this yields
	\begin{align}
	\| (\boldsymbol\Theta-\widehat{\boldsymbol\Theta})\mathbf\Pi \|_F^2 &\le 2\sigma\sum_{n=1}^n 
	(\boldsymbol\Xi\mathbf\Pi)_i^\top(\widehat\boldsymbol\theta_i-\boldsymbol\theta_i) + \lambda \sum_{i=1}^n \big\{ \|\boldsymbol\theta_i\|_2 - 
	\|\widehat\boldsymbol\theta_i\|_2\big\}.
	\end{align}

Using the Cauchy-Schwarz inequality, we have on the event
	\begin{equation} \mathcal{A} = \Big\{ \max_{i\in [n]} \big\| (\boldsymbol\Xi\mathbf\Pi)_i \big\|_2 \le \frac{\lambda}{4\sigma} \Big\}
	\end{equation}
	that
	\begin{align}
	\|(\boldsymbol\Theta-\widehat{\boldsymbol\Theta})\mathbf\Pi\|_F^2
	&\le \frac\lambda2 \sum_{i=1}^n \Big\{ \|\widehat\boldsymbol\theta_i-\boldsymbol\theta_i\|_2
			+ 2 \|\boldsymbol\theta_i\|_2 - 2 \|\widehat\boldsymbol\theta_i\|_2 \Big\} \\
	&\le \frac{3\lambda}2 \sum_{i\in S} \|\widehat\boldsymbol\theta_i-\boldsymbol\theta_i\|_2 -
			\frac\lambda2 \sum_{i\not\in S} \|\widehat\boldsymbol\theta_i-\boldsymbol\theta_i\|_2,
	\end{align}
	where we used the triangular inequality.

The last inequality implies that
	\begin{align} \sum_{i\not\in S} \|\widehat\boldsymbol\theta_i-\boldsymbol\theta_i\|_2\le 3\sum_{i\in S} \|\widehat\boldsymbol\theta_i-\boldsymbol\theta_i\|_2.
	\end{align}

Furthermore, using the Cauchy-Schwarz inequality, we get
	\begin{equation}
	\|(\boldsymbol\Theta-\widehat\boldsymbol\Theta)\mathbf\Pi\|_F^2 \le \frac{3\lambda}2 \sqrt{s} \|\boldsymbol\Theta-\widehat\boldsymbol\Theta\|_F.
	\end{equation}

We can then apply Lemma~\ref{lemme_Pi}, since~(\ref{theoreme_bornesuperieure1_2}) 
	ensures that the condition is satisfied with $a=3$: provided that $s\le n/16$, we have
	\begin{equation}
	\frac12 \|\widehat\boldsymbol\Theta-\boldsymbol\Theta\|_F^2 \le \frac{3\lambda}2 \sqrt{s} \|\widehat\boldsymbol\Theta-\boldsymbol\Theta\|_F,
	\end{equation}
	so that
	\begin{equation}
	\|\widehat\boldsymbol\Theta-\boldsymbol\Theta\|_F \le 3 \lambda \sqrt{s}.
	\end{equation}

We first show that with high probability the weights $w_i$
vanish outside the support $S$.

\begin{lemma} In the event $\Omega_1\cap \Omega_2$, where
\begin{align}
\Omega_2 &= \Big\{\max_i\big|\|\bar\boldsymbol\xi_i\|_2^2-(1-\nicefrac1n)p\big|\le 0.5\gamma^2\Big\},
\end{align}
we have $w_i=0$ for every $i\not\in S$. Furthermore, under the condition
$\gamma^2 > 4\log(4n/\delta)+4 \{p\log(4n/\delta)\}^{1/2}$, the probability of
$\Omega_2$ is at least $1-\delta/2$.
\end{lemma}

We will now evaluate the first and the third terms of the right-hand side.	
	\begin{lemma} There is a sequence of standard Gaussian random variables 
	$\eta_1,\ldots,\eta_n$ such that in the event $\Omega_1\cap\Omega_2$, it holds
	\begin{align}
	\|\boldsymbol Z_i - \sigma\bar\boldsymbol\xi_i\|_2|w_i-1|
		\le 2\sigma|\eta_i| + \big\{|2\sigma\bar\boldsymbol\xi_i^\top\widetilde\boldsymbol\Delta_n|\big\}^{1/2} + 
			1.96\sigma\gamma. \end{align}
	\end{lemma}

Let us introduce the $p\times s$ matrix $\boldsymbol\Xi_S = [\,\bar\boldsymbol\xi_i; i\in S\,]$ (the matrix
	obtained by concatenating the vectors $\bar\boldsymbol\xi_i$ with subscript $i$ running over $S$).
	Using the H\"older inequality, one can check that
	\begin{align}
	\sum_{i\in S}\big\{2\sigma|\bar\boldsymbol\xi_i^\top\widetilde\boldsymbol\Delta_n|\big\}^{1/2}
			&\le \sqrt{2\sigma}\, s^{3/4} \bigg(\sum_{i\in S} |\bar\boldsymbol\xi_i^\top\widetilde\boldsymbol\Delta_n|^2
				\bigg)^{1/4}\\
			&= \sqrt{2\sigma}\, s^{3/4} \|\boldsymbol\Xi_S^\top\widetilde\boldsymbol\Delta_n\|_2^{1/2}\\
			&\le \sqrt{2\sigma}\, s^{3/4} \|\boldsymbol\Xi_S\|^{1/2}\|\widetilde\boldsymbol\Delta_n\|_2^{1/2}. \end{align}

Finally, the third term in the right-hand side of \eqref{Z1} can be bounded as follows:
	\begin{equation}
		\Big\| \sum_{i\in S}\bar\boldsymbol\xi_iw_i\Big\|_2 = \|\boldsymbol\Xi_S \boldsymbol w\|_2\le \sqrt{s}\,\|\boldsymbol\Xi_S\|. \end{equation}

Combining \eqref{Z1}, \eqref{Z2}, \eqref{Z3} and \eqref{Z4}, we arrive at
	\begin{align}
	\|\boldsymbol L(\widehat{\boldsymbol\Theta}-\boldsymbol\Theta) \|_2
		&\le 2\sigma\sum_{i\in S}\big(|\eta_i| + \big\{2\sigma|\widetilde\boldsymbol\Delta_n^\top 
		\bar\boldsymbol\xi_i|\big\}^{1/2}\big) +1.96\,\sigma s\gamma
			+ {s}\big\|\widetilde\boldsymbol\Delta_n\big\|_2  + \sigma\sqrt{s}\,\|\boldsymbol\Xi_S\|\\
		&\le 2\sigma\sum_{i\in S}|\eta_i|+2.21\,\sigma s\gamma+\sqrt{2\sigma}\, s^{3/4} \|\boldsymbol\Xi_S\|^{1/2}
		\big\|\widetilde\boldsymbol\Delta_n\big\|_2^{1/2}+\sigma\sqrt{s}\,\|\boldsymbol\Xi_S\|\\
		&\le 2\sigma\sum_{i\in S}|\eta_i| +2.34\,\sigma s\gamma + 
		2\sigma\sqrt{s}\,\|\boldsymbol\Xi_S\|. \end{align}

We denote by $\boldsymbol u_i\in\mathbb R^n$ the column vector corresponding to the $i$-th row of $\mathbf U$.
    On the one hand, since $\nicefrac1n\mathbf J_n$ is an orthogonal projection matrix, we have by the Pythagorean theorem
	\begin{align}
		\|\mathbf\Pi\boldsymbol u^i\|_2^2 &= \|\boldsymbol u^i\|_2^2 -\frac1{n^2} \|\mathbf J_n\boldsymbol u^i\|_2^2.
	\end{align}

In particular, this implies that
	\begin{align} \|\mathbf U\mathbf\Pi\|_F^2 &= \|\mathbf U\|_F^2 -\frac1{n^2} \|\mathbf U\mathbf J_n\|_F^2.
	\end{align}

On the other hand,
	\begin{align}
		\|\mathbf U\mathbf J_n\|_F &= \|\mathbf \mathbf U 1_n\mathbf 1_n^\top\|_F =\sqrt{n}\, \|\mathbf U \mathbf 1_n^\top\|_2 = \sqrt{n}\, \Big\|\sum_{i=1}^n \boldsymbol u_i\Big\|_2
        \le \sqrt{n}\, \sum_{i=1}^n \|\boldsymbol u_i\|_2.
	\end{align}

Using \eqref{cone_cond} and the Cauchy-Schwarz inequality, we get
	\begin{align}
		\sum_{i=1}^n \|\boldsymbol u_i\|_2 &\le (1+a)\sum_{i\in S} \|\boldsymbol u_i\|_2 \le (1+a)|S|^{1/2}\Big(\sum_{i\in S} \|\boldsymbol u_i\|^2_2\Big)^{1/2} \le (1+a)|S|^{1/2}\|\mathbf U\|_F.
	\end{align}

The conditions of the lemma directly imply that $\epsilon_{k+1}^2\le p$. Therefore,
		\begin{align} \epsilon_{k+1} \le \frac{33sp^{1/4}\epsilon_k^{1/2}}{n}\vee 2a.
		\end{align}

It is easy to see that the last inequality is never true, implying thus that
		$w_i=0$. Indeed,
		\begin{align}
				\sqrt{p+\gamma^2} -\sqrt{p+0.5\gamma^2}  
					& = \frac{0.5\gamma^2}{\sqrt{p+\gamma^2} +\sqrt{p+0.5\gamma^2}}\\
					& > \frac{0.5\gamma^2}{\sqrt{p+\gamma^2} +\sqrt{p+\gamma^2}}
					= \frac{\gamma^2}{4\sqrt{p+\gamma^2}}.
		\end{align}

The definition of $\boldsymbol Z_i$ yields
	\begin{align}
	\|\boldsymbol Z_i-\sigma\bar\boldsymbol\xi_i\|_2|w_i-1|  &= \|\boldsymbol Z_i-\sigma\bar\boldsymbol\xi_i\|_2 \min\bigg\{ 1,
	\frac{\sigma\gamma}{\big(\|\boldsymbol Z_i\|^2_2-\sigma_{n,p}^2\big)^{1/2}_+} \bigg\}.
	\end{align}

Taking in this inequality $a = \|\boldsymbol Z_i-\sigma\bar\boldsymbol\xi_i\|_2$, 
	$c = \sigma^2\eta_i^2 - \|\sigma\bar\boldsymbol\xi_i\|_2^2
		+2\sigma\|\widetilde\boldsymbol\Delta_n\|_2|\eta_i|-2\sigma\bar\boldsymbol\xi_i^\top\widetilde\boldsymbol\Delta_n + 
		\sigma^2_{n,p}$, $b=\sigma|\eta_i|$ and $d=\sigma\gamma$, we arrive at
	\begin{align}
	\|\boldsymbol Z_i-\sigma\bar\boldsymbol\xi_i\|_2|w_i-1|
		&\le 2\sigma|\eta_i| + \sigma\gamma+ \|\widetilde\boldsymbol\Delta_n\|_2\\
		&\qquad+\sqrt{(\sigma_{n,p}^2-\sigma^2\|\bar\boldsymbol\xi_i\|_2^2)_+}
		+\sqrt{(2\sigma\bar\boldsymbol\xi_i^\top\widetilde\boldsymbol\Delta_n -\|\widetilde\boldsymbol\Delta_n\|_2^2)_+}.
	\end{align}

First assume that $x\ge 4d$. Combining the relation
	\begin{align}
		\mathbf E\big(\eta\, \mathds{1}_{\eta\ge d+x}\big) &= (d+x)\mathbf P(\eta\ge d+x)+\int_x^{+\infty} \mathbf P(\eta\ge d+t)\,dt
	\end{align}
	with Lemma~\ref{lemme_chideux}, we get
	\begin{align}
		\mathbf E\big(\eta\, \mathds{1}_{\eta\ge d+x}\big)
		&\le (d+x) e^{-x/4} + \int_x^{+\infty} e^{-t/4}\, dt\\
		&\le (4+d+x)e^{-x/4}\le (4d+x)e^{-x/4}\le 2xe^{-x/4}. \phantom{\int_0^{+\infty}}
	\end{align}

Now assume that $x<4d$. Then, using the Cauchy-Schwarz inequality and
	Lemma~\ref{lemme_chideux},
	\begin{align}
	\mathbf E\big(\eta\, \mathds{1}_{\eta\ge d+x}\big) \le \sqrt{d(d+2)} e^{-x^2/32d}.
	\end{align}

