initialization $I \gets [n]$ and $\widehat S \gets \varnothing$.

\Repeat{$I$ is empty or $\widehat J$ is empty}{
Set $\mathcal I \gets \big\{J\subseteq I : \|\boldsymbol L(\mathbf Y_{J})\|_2^2
\ge 12\sigma^2 (|J|p + \lambda |J|^2)\big\}$.\;
\eIf{$\mathcal I =\varnothing$}{$\widehat J\gets\varnothing$\;
}{
Set $\widehat J \gets \text{arg}\min\big\{|J| : J\in\mathcal I\big\}$.\;
}
Update $\widehat S \gets \widehat S \cup \widehat J$.\;
Update $I \gets I\setminus \widehat J$.

